import{_ as e,C as a,c as o,o as i,a0 as l,b as n,w as r,a as t,G as s,a1 as c}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Comunicación en equipo","description":"","frontmatter":{},"headers":[],"relativePath":"es/education/team-player/communication.md","filePath":"es/education/team-player/communication.md"}');const d=e({name:"es/education/team-player/communication.md"},[["render",function(e,u,d,p,m,h){const q=a("Mermaid");return i(),o("div",null,[u[1]||(u[1]=l('<h1 id="comunicacion-en-equipo" tabindex="-1">Comunicación en equipo <a class="header-anchor" href="#comunicacion-en-equipo" aria-label="Permalink to &quot;Comunicación en equipo&quot;">​</a></h1><p>La comunicación eficaz es lo que transforma a un grupo de personas en un equipo. En la petanca, donde la estrategia cambia constantemente y la presión es alta, la forma de comunicarse puede determinar el resultado.</p><div class="tip custom-block"><p class="custom-block-title">La gran idea</p><p><strong>La comunicación es lo que transforma a los individuos en un equipo.</strong> Una comunicación clara, específica y de apoyo bajo presión separa a los buenos equipos de los excelentes.</p></div><h2 id="el-ciclo-de-la-comunicacion" tabindex="-1">El ciclo de la comunicación <a class="header-anchor" href="#el-ciclo-de-la-comunicacion" aria-label="Permalink to &quot;El ciclo de la comunicación&quot;">​</a></h2><p>La buena comunicación en equipo sigue un ciclo:</p>',5)),(i(),n(c,null,{default:r(()=>[s(q,{id:"mermaid-17",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BObservar%5D%20--%3E%20B%5BCompartir%5D%0A%20%20%20%20B%20--%3E%20C%5BConversar%5D%0A%20%20%20%20C%20--%3E%20D%5BDecidir%5D%0A%20%20%20%20D%20--%3E%20E%5BEjecutar%5D%0A%20%20%20%20E%20--%3E%20F%5BRevisar%5D%0A%20%20%20%20F%20--%3E%20A%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23f3e5f5%0A"})]),fallback:r(()=>[...u[0]||(u[0]=[t(" Loading... ",-1)])]),_:1})),u[2]||(u[2]=l('<table tabindex="0"><thead><tr><th>Paso</th><th>Acción</th><th>Ejemplo</th></tr></thead><tbody><tr><td><strong>Observar</strong></td><td>Observa lo que está pasando</td><td>Terreno, posiciones, oponentes</td></tr><tr><td><strong>Compartir</strong></td><td>Cuéntales a tus compañeros lo que ves</td><td>&quot;El terreno se inclina hacia la izquierda allí&quot;</td></tr><tr><td><strong>Conversar</strong></td><td>Intercambio de perspectivas</td><td>&quot;¿Debería bloquear o ir por el punto?&quot;</td></tr><tr><td><strong>Decidir</strong></td><td>Acordar el enfoque</td><td>&quot;Vamos a probar el globo alto&quot;</td></tr><tr><td><strong>Ejecutar</strong></td><td>Hazlo con compromiso</td><td>Concentración total en el lanzamiento</td></tr><tr><td><strong>Revisar</strong></td><td>Aprender de los resultados</td><td>&quot;Eso funcionó bien&quot; o &quot;La próxima vez...&quot;</td></tr></tbody></table><h2 id="cuando-comunicarse" tabindex="-1">Cuándo comunicarse <a class="header-anchor" href="#cuando-comunicarse" aria-label="Permalink to &quot;Cuándo comunicarse&quot;">​</a></h2><h3 id="antes-de-cada-fin" tabindex="-1">Antes de cada fin <a class="header-anchor" href="#antes-de-cada-fin" aria-label="Permalink to &quot;Antes de cada fin&quot;">​</a></h3><ul><li>Evaluar el terreno juntos</li><li>Discutir el enfoque general</li><li>Aclarar quién lanza y cuándo</li><li>Establezca el tono (tranquilo, centrado)</li></ul><h3 id="durante-el-final" tabindex="-1">Durante el final <a class="header-anchor" href="#durante-el-final" aria-label="Permalink to &quot;Durante el final&quot;">​</a></h3><ul><li>Compartir observaciones (&quot;El terreno se inclina hacia la izquierda&quot;)</li><li>Coordinar la estrategia (&quot;¿Debería intentar bloquear o ir por el punto?&quot;)</li><li>Ofrecer apoyo (&quot;Tómate tu tiempo, tú puedes&quot;)</li><li>Ajustar los planes a medida que cambia la situación</li></ul><h3 id="entre-extremos" tabindex="-1">Entre extremos <a class="header-anchor" href="#entre-extremos" aria-label="Permalink to &quot;Entre extremos&quot;">​</a></h3><ul><li>Breve informe (qué funcionó y qué no)</li><li>Reiniciar mentalmente</li><li>Prepárate para el próximo final</li><li>Manténgase conectado como equipo</li></ul><h3 id="despues-del-juego" tabindex="-1">Después del juego <a class="header-anchor" href="#despues-del-juego" aria-label="Permalink to &quot;Después del juego&quot;">​</a></h3><ul><li>Informe completo (cuando corresponda)</li><li>Reconocer contribuciones</li><li>Identificar aprendizajes</li><li>Mantener la relación</li></ul><h2 id="como-comunicarse" tabindex="-1">Cómo comunicarse <a class="header-anchor" href="#como-comunicarse" aria-label="Permalink to &quot;Cómo comunicarse&quot;">​</a></h2><h3 id="sea-claro-y-especifico" tabindex="-1">Sea claro y específico <a class="header-anchor" href="#sea-claro-y-especifico" aria-label="Permalink to &quot;Sea claro y específico&quot;">​</a></h3><p><strong>Vago:</strong> &quot;Intenta acercarte&quot; <strong>Despejado:</strong> &quot;Apunta al lado izquierdo del gato, a unos 20 cm hacia afuera&quot;</p><p><strong>Vago:</strong> &quot;Buen intento&quot; <strong>Claro:</strong> &quot;Buen peso, un poco a la izquierda de la línea&quot;</p><h3 id="sea-constructivo" tabindex="-1">Sea constructivo <a class="header-anchor" href="#sea-constructivo" aria-label="Permalink to &quot;Sea constructivo&quot;">​</a></h3><p>Centrarse en las soluciones, no en los problemas:</p><p><strong>Enfocado en el problema:</strong> &quot;Sigues fallando hacia la derecha&quot; <strong>Enfocado en la solución:</strong> &quot;¿Quizás podrías intentar apuntar un poco más hacia la izquierda para compensar?&quot;</p><h3 id="sea-solidario" tabindex="-1">Sea solidario <a class="header-anchor" href="#sea-solidario" aria-label="Permalink to &quot;Sea solidario&quot;">​</a></h3><p>Tu tono importa tanto como tus palabras:</p><ul><li>Mantén la calma, incluso cuando te sientas frustrado</li><li>Utilice un lenguaje corporal alentador</li><li>Reconozca el esfuerzo, no sólo los resultados</li><li>Construye, no destruyas</li></ul><h3 id="escuchar-activamente" tabindex="-1">Escuchar activamente <a class="header-anchor" href="#escuchar-activamente" aria-label="Permalink to &quot;Escuchar activamente&quot;">​</a></h3><p>La comunicación es bidireccional:</p><ul><li>Preste toda su atención cuando sus compañeros de equipo hablen.</li><li>Haga preguntas aclaratorias</li><li>Reconoce lo que has escuchado</li><li>No interrumpir ni despedir</li></ul><h2 id="desafios-de-la-comunicacion" tabindex="-1">Desafíos de la comunicación <a class="header-anchor" href="#desafios-de-la-comunicacion" aria-label="Permalink to &quot;Desafíos de la comunicación&quot;">​</a></h2><h3 id="desacuerdo-sobre-la-estrategia" tabindex="-1">Desacuerdo sobre la estrategia <a class="header-anchor" href="#desacuerdo-sobre-la-estrategia" aria-label="Permalink to &quot;Desacuerdo sobre la estrategia&quot;">​</a></h3><p><strong>Mal enfoque:</strong></p><ul><li>Insiste en tu camino</li><li>Ponerse a la defensiva</li><li>Ceder con resentimiento</li><li>Discutir durante el juego</li></ul><p><strong>Mejor enfoque:</strong></p><ol><li>Comparte tu perspectiva claramente</li><li>Escuchenlos completamente</li><li>Discuta brevemente los pros y los contras</li><li>Decidir juntos (o dejar la decisión en manos del líder designado)</li><li>Comprometerse plenamente con la decisión</li><li>Reseña después del partido</li></ol><h3 id="despues-del-error-de-un-companero-de-equipo" tabindex="-1">Después del error de un compañero de equipo <a class="header-anchor" href="#despues-del-error-de-un-companero-de-equipo" aria-label="Permalink to &quot;Después del error de un compañero de equipo&quot;">​</a></h3><p><strong>Lo que necesitan:</strong></p><ul><li>Reconocimiento rápido</li><li>Permiso para seguir adelante</li><li>Confianza en que todavía confías en ellos</li><li>Concéntrese en el siguiente lanzamiento</li></ul><p><strong>Qué decir:</strong></p><ul><li>&quot;No hay problema, el siguiente&quot;</li><li>&quot;Buena suerte, te toca el siguiente&quot;</li><li>&quot;Seguimos en esto&quot;</li><li><em>A veces basta con un gesto o una palmadita</em></li></ul><p><strong>Qué NO decir:</strong></p><ul><li>Nada (el silencio parece un juicio)</li><li>&quot;Está bien&quot; (puede sonar despectivo)</li><li>¿Algo sobre lo que salió mal? (no ahora)</li><li>Frustración visible (el lenguaje corporal cuenta)</li></ul><h3 id="cuando-cometes-un-error" tabindex="-1">Cuando cometes un error <a class="header-anchor" href="#cuando-cometes-un-error" aria-label="Permalink to &quot;Cuando cometes un error&quot;">​</a></h3><p><strong>Qué hacer:</strong></p><ul><li>Breve reconocimiento (&quot;Mi error&quot;)</li><li>No te disculpes demasiado</li><li>No pongas excusas</li><li>Reiniciar y concentrarse en el siguiente lanzamiento</li><li>Confía en que tus compañeros de equipo te apoyarán</li></ul><h3 id="tension-en-el-equipo" tabindex="-1">Tensión en el equipo <a class="header-anchor" href="#tension-en-el-equipo" aria-label="Permalink to &quot;Tensión en el equipo&quot;">​</a></h3><p>Si aumenta la tensión durante un juego:</p><ol><li>Reconoce que está sucediendo</li><li>Respira antes de responder</li><li>Concéntrese en el juego, no en el conflicto.</li><li>Abordarlo adecuadamente después del juego</li><li>No dejes que afecte tu juego</li></ol><h2 id="comunicacion-no-verbal" tabindex="-1">Comunicación no verbal <a class="header-anchor" href="#comunicacion-no-verbal" aria-label="Permalink to &quot;Comunicación no verbal&quot;">​</a></h2><p>Gran parte de la comunicación en equipo es no verbal:</p><h3 id="senales-positivas" tabindex="-1">Señales positivas <a class="header-anchor" href="#senales-positivas" aria-label="Permalink to &quot;Señales positivas&quot;">​</a></h3><ul><li>Contacto visual</li><li>Cabeceo</li><li>Pulgares hacia arriba</li><li>Postura relajada</li><li>Moviéndose hacia los compañeros de equipo</li><li>Sonriendo (cuando sea apropiado)</li></ul><h3 id="senales-negativas-evitelas" tabindex="-1">Señales negativas (evítelas) <a class="header-anchor" href="#senales-negativas-evitelas" aria-label="Permalink to &quot;Señales negativas (evítelas)&quot;">​</a></h3><ul><li>Poniendo los ojos en blanco</li><li>Dándose la vuelta</li><li>Brazos cruzados</li><li>Suspirando</li><li>Sacudiendo la cabeza</li><li>Lenguaje corporal tenso</li></ul><p><strong>Recuerda:</strong> Tus compañeros lo ven todo. Tu lenguaje corporal influye en su confianza y rendimiento.</p><h2 id="desarrollando-habitos-de-comunicacion" tabindex="-1">Desarrollando hábitos de comunicación <a class="header-anchor" href="#desarrollando-habitos-de-comunicacion" aria-label="Permalink to &quot;Desarrollando hábitos de comunicación&quot;">​</a></h2><h3 id="comunicacion-practica" tabindex="-1">Comunicación práctica <a class="header-anchor" href="#comunicacion-practica" aria-label="Permalink to &quot;Comunicación práctica&quot;">​</a></h3><p>No esperes a que la competencia se comunique:</p><ul><li>Practicar debates estratégicos en la formación</li><li>Darnos retroalimentación regularmente</li><li>Desarrolla el lenguaje de tu equipo</li><li>Genere comodidad con una conversación honesta</li></ul><h3 id="desarrollar-senales-de-equipo" tabindex="-1">Desarrollar señales de equipo <a class="header-anchor" href="#desarrollar-senales-de-equipo" aria-label="Permalink to &quot;Desarrollar señales de equipo&quot;">​</a></h3><p>Algunos equipos desarrollan taquigrafía:</p><ul><li>Señales manuales para la estrategia</li><li>Palabras clave para situaciones</li><li>Frases rápidas con significado compartido</li></ul><h3 id="registros-regulares" tabindex="-1">Registros regulares <a class="header-anchor" href="#registros-regulares" aria-label="Permalink to &quot;Registros regulares&quot;">​</a></h3><p>Fuera de los juegos:</p><ul><li>¿Cómo estamos trabajando juntos?</li><li>¿Qué va bien?</li><li>¿Qué podría ser mejor?</li><li>¿Hay algún problema que abordar?</li></ul><h2 id="el-papel-del-capitan" tabindex="-1">El papel del capitán <a class="header-anchor" href="#el-papel-del-capitan" aria-label="Permalink to &quot;El papel del capitán&quot;">​</a></h2><p>Si su equipo tiene un líder designado:</p><p><strong>Responsabilidades del capitán:</strong></p><ul><li>Decisión final cuando el equipo no está de acuerdo</li><li>Estableciendo el tono y la energía</li><li>Gestión de la dinámica del equipo</li><li>Mantener la concentración bajo presión</li></ul><p><strong>Todos los demás:</strong></p><ul><li>Comparte tu perspectiva</li><li>Apoyar la decisión una vez tomada</li><li>Ayuda a mantener la energía del equipo</li><li>Asume la responsabilidad de tu rol</li></ul><h2 id="conclusion-clave" tabindex="-1">Conclusión clave <a class="header-anchor" href="#conclusion-clave" aria-label="Permalink to &quot;Conclusión clave&quot;">​</a></h2><blockquote><p>Los grandes equipos hablan entre sí, no sobre los demás. Se comunican con honestidad, respeto y un compromiso compartido con el éxito.</p></blockquote><p>Practica la comunicación como si lanzaras. Es una habilidad que mejora con la atención.</p>',68))])}]]);export{u as __pageData,d as default};
